  table.set("-0645", "reject");
  table.set("-0500", "reject");
  table.set("-0530", "reject");
  table.set("-0545", "reject");
  table.set("-0400", "reject");
  table.set("-0430", "reject");
  table.set("-0445", "reject");
  table.set("-0300", "reject");
  table.set("-0330", "reject");
  table.set("-0345", "reject");
  table.set("-0200", "reject");
  table.set("-0230", "reject");
  table.set("-0245", "reject");
  table.set("-0100", "reject");
  table.set("-0130", "reject");
  table.set("-0145", "reject");
  table.set("+0000", "reject");
  table.set("+0030", "reject");
  table.set("+0045", "reject");
  table.set("+0100", "reject");
  table.set("+0130", "reject");
  table.set("+0145", "reject");
  table.set("+0200", "reject");
  table.set("+0230", "reject");
  table.set("+0245", "reject");
  table.set("+0300", "reject");
  table.set("+0330", "reject");
  table.set("+0345", "reject");
  table.set("+0400", "reject");
  table.set("+0430", "reject");
  table.set("+0445", "reject");
  table.set("+0500", "reject");
  table.set("+0530", "reject");
  table.set("+0545", "reject");
  table.set("+0600", "reject");
  table.set("+0630", "reject");
  table.set("+0645", "reject");
  table.set("+0700", "reject");
  table.set("+0730", "reject");
  const key = match[1] + match[2] + (match[3] || "00");
  if (compact && table.get(key) === "reject") rejectCompact(key);
  if (compact) acceptCompact(key);
  return {hours, minutes, compact};
}

